import contextlib
import io
import unittest

from textkit.cli import main
from textkit.rot import rot


class RotTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_wrap_and_case(self):
        self.assertEqual(rot("xyzXYZ", 3), "abcABC")

    def test_negative_and_large(self):
        self.assertEqual(rot("abc", -1), "zab")
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", -53), "zab")

    def test_other_chars(self):
        self.assertEqual(rot("é1 ,ß", 5), "é1 ,ß")

    def test_bad_n(self):
        for bad in (1.5, "1", True, None):
            with self.assertRaises(ValueError):
                rot("abc", bad)


class RotCliTests(unittest.TestCase):
    def run_cli(self, *argv):
        out, err = io.StringIO(), io.StringIO()
        code = 0
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                code = main(list(argv))
            except SystemExit as e:
                code = e.code
        return code, out.getvalue(), err.getvalue()

    def test_default(self):
        self.assertEqual(self.run_cli("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative(self):
        self.assertEqual(self.run_cli("rot", "abc", "--n", "-1")[:2], (0, "zab\n"))

    def test_float(self):
        code, out, err = self.run_cli("rot", "abc", "--n", "1.5")
        self.assertEqual(code, 2)
        self.assertIn("error:", err)


if __name__ == "__main__":
    unittest.main()
